1402	// validatePlanRules 校验阶梯方案的标识、名称、月费与阶梯规则本身自洽：
1403	// 月费为非负整数分，至少一档，有限上限为严格递增的正整数，最后一档无
1404	// 上限，单价非负。
1405	func validatePlanRules(p *plan) error {
1406		if p.ID == "" || p.Name == "" {
1407			return fmt.Errorf("方案 %q 的标识或名称为空", p.ID)
1408		}
1409		if p.MonthlyFee < 0 {
1410			return fmt.Errorf("方案 %q 的月费为负", p.ID)
1411		}
1412		if len(p.Tiers) == 0 {
1413			return fmt.Errorf("方案 %q 至少需要一档阶梯", p.ID)
1414		}
1415		prev := int64(0)
1416		for i, t := range p.Tiers {
1417			if t.Price < 0 {
1418				return fmt.Errorf("方案 %q 第 %d 档单价为负", p.ID, i+1)
1419			}
1420			if i == len(p.Tiers)-1 {
1421				if t.Limit != 0 {
1422					return fmt.Errorf("方案 %q 最后一档必须无上限", p.ID)
1423				}
1424			} else {
1425				if t.Limit <= 0 {
1426					return fmt.Errorf("方案 %q 第 %d 档上限必须是正整数", p.ID, i+1)
1427				}
1428				if t.Limit <= prev {
1429					return fmt.Errorf("方案 %q 的有限上限必须严格递增", p.ID)
1430				}
1431				prev = t.Limit
1432			}
1433		}
1434		return nil
1435	}
