1437	// tiersEqual 判定两份阶梯规则完全相同。
1438	func tiersEqual(a, b []tier) bool {
1439		if len(a) != len(b) {
1440			return false
1441		}
1442		for i := range a {
1443			if a[i] != b[i] {
1444				return false
1445			}
1446		}
1447		return true
1448	}
