1541	// save 整体原子落盘：先写临时文件并同步，再 rename 覆盖。
1542	// 只有完整保存成功后调用方才会向用户报告成功。
1543	func (s *state) save() error {
1544		if err := s.validate(); err != nil {
1545			return fmt.Errorf("拒绝写入不一致的数据: %w", err)
1546		}
1547		data, err := json.MarshalIndent(s, "", "  ")
1548		if err != nil {
1549			return fmt.Errorf("序列化数据失败: %w", err)
1550		}
1551		data = append(data, '\n')
1552	
1553		tmp := s.path + ".tmp"
1554		f, err := os.OpenFile(tmp, os.O_WRONLY|os.O_CREATE|os.O_TRUNC, 0o644)
1555		if err != nil {
1556			return fmt.Errorf("写入临时数据文件失败: %w", err)
1557		}
1558		if _, err := f.Write(data); err != nil {
1559			f.Close()
1560			os.Remove(tmp)
1561			return fmt.Errorf("写入临时数据文件失败: %w", err)
1562		}
1563		if err := f.Sync(); err != nil {
1564			f.Close()
1565			os.Remove(tmp)
1566			return fmt.Errorf("同步数据文件失败: %w", err)
1567		}
1568		if err := f.Close(); err != nil {
1569			os.Remove(tmp)
1570			return fmt.Errorf("关闭数据文件失败: %w", err)
1571		}
1572		if err := os.Rename(tmp, s.path); err != nil {
1573			os.Remove(tmp)
1574			return fmt.Errorf("替换数据文件失败: %w", err)
1575		}
1576		if dir, err := os.Open(filepath.Dir(s.path)); err == nil {
1577			dir.Sync()
1578			dir.Close()
1579		}
1580		return nil
1581	}
