1812	// 被更正移出或整笔转出到其他客户），按操作序号升序。收款的首次登记客户
1813	// 永久保留在 payment.CustomerID，归属经归属更正变化，故不能只按该字段过滤。
1814	func paymentsEverFor(s *state, customerID, month string) []*payment {
1815		var list []*payment
1816		for _, p := range s.Payments {
1817			// 该收款是否曾归属于该客户：首次登记客户或某次归属更正的目标客户。
1818			everOwned := p.CustomerID == customerID
1819			if !everOwned {
1820				for _, c := range reassignsFor(s, p.ID) {
1821					if c.TargetCustomerID == customerID {
1822						everOwned = true
1823						break
1824					}
1825				}
1826			}
1827			if !everOwned {
1828				continue
1829			}
1830			involved := false
1831			// 沿更正链只在归属为该客户期间检查分配是否涉及该月：首次分配（首次
1832			// 登记客户）或某次以该客户为目标的更正的新分配涉及该月即可。
1833			if p.CustomerID == customerID && p.amountFor(month) > 0 {
1834				involved = true
1835			}
1836			if !involved {
1837				for _, c := range s.Corrections {
1838					if c.PaymentID == p.ID && allocAmountFor(c.Allocations, month) > 0 {
1839						owner := c.TargetCustomerID
1840						if !c.Reassign {
1841							owner = paymentOwnerAt(s, p, c.Seq-1)
1842						}
1843						if owner == customerID {
1844							involved = true
1845							break
1846						}
1847					}
1848				}
1849			}
1850			if involved {
1851				list = append(list, p)
1852			}
1853		}
1854		sort.Slice(list, func(i, j int) bool { return list[i].Seq < list[j].Seq })
1855		return list
1856	}
