1859	// 指定月份计入并扣除退款后的实收之和。收款可能经归属更正来自其他客户，
1860	// 归属按归属更正时间线取当前值；已整笔转出（当前归属为其他客户）或已撤销
1861	// 的收款不计入。各笔净额（分配减累计退款）均为非负整数，用非负 64 位加法
1862	// 累加，溢出时返回错误。
1863	func paymentReceived(s *state, customerID, month string) (int64, error) {
1864		var received int64
1865		for _, p := range s.Payments {
1866			if p.Revoked || paymentOwner(s, p) != customerID {
1867				continue
1868			}
1869			amt := allocAmountFor(currentAllocations(s, p), month) - refundedForMonth(s, p.ID, month)
1870			if amt <= 0 {
1871				continue
1872			}
1873			var err error
1874			received, err = add64(received, amt)
1875			if err != nil {
1876				return 0, err
1877			}
1878		}
1879		return received, nil
1880	}
