1920	// billTotals 计算全部未撤销调整的净额与当前应付（原总金额 + 净额）。
1921	// 净额按 128 位精确求和（与顺序无关），再校验应付落在
1922	// [0, 有符号 64 位最大值] 内，全程整数运算。
1923	func billTotals(b *bill, adjs []*adjustment) (net, payable int64, err error) {
1924		var amounts []int64
1925		for _, a := range adjs {
1926			if !a.Revoked {
1927				amounts = append(amounts, a.Amount)
1928			}
1929		}
1930		net, err = sumSigned64(amounts...)
1931		if err != nil {
1932			return 0, 0, err
1933		}
1934		payable, err = addSigned64(b.TotalFee, net)
1935		if err != nil {
1936			return 0, 0, err
1937		}
1938		if payable < 0 {
1939			return 0, 0, errPayableOutOfRange
1940		}
1941		return net, payable, nil
1942	}
