258	func cmdCustomerAdd(dir, id, name, priceText string) error {
259		if strings.TrimSpace(id) == "" {
260			return fmt.Errorf("客户标识不能为空")
261		}
262		if strings.TrimSpace(name) == "" {
263			return fmt.Errorf("客户名称不能为空")
264		}
265		price, err := parsePrice(priceText)
266		if err != nil {
267			return err
268		}
269	
270		s, err := loadStore(dir)
271		if err != nil {
272			return err
273		}
274		if _, exists := s.Customers[id]; exists {
275			return fmt.Errorf("客户标识 %q 已存在，客户单价创建后不可修改", id)
276		}
277		s.Customers[id] = &customer{ID: id, Name: name, Price: price}
278		if err := s.save(); err != nil {
279			return err
280		}
281		fmt.Fprintf(stdout, "已登记客户 %q（%s），固定单价 %d 分（%s）\n", id, name, price, moneyFen(price))
282		return nil
283	}
