285	func parsePrice(text string) (int64, error) {
286		text = strings.TrimSpace(text)
287		price, err := strconv.ParseInt(text, 10, 64)
288		if err != nil {
289			return 0, fmt.Errorf("单价 %q 不是有符号 64 位整数范围内的整数: %w", text, err)
290		}
291		if price < 0 {
292			return 0, fmt.Errorf("单价必须是非负整数分，收到 %d", price)
293		}
294		return price, nil
295	}
