423	// parseUsageFile 完整读取 CSV，做格式层面的解析；业务层面的校验在调用方完成。
424	func parseUsageFile(r io.Reader) ([]*parsedRow, []string) {
425		cr := csv.NewReader(r)
426		cr.FieldsPerRecord = 4
427		cr.TrimLeadingSpace = true
428	
429		header, err := cr.Read()
430		if err == io.EOF {
431			return nil, []string{"文件为空：首行必须是表头 " + usageHeader}
432		}
433		if err != nil {
434			return nil, []string{fmt.Sprintf("无法读取表头：%v（首行必须是 %s）", err, usageHeader)}
435		}
436		for i := range header {
437			header[i] = strings.TrimSpace(header[i])
438		}
439		if len(header) != 4 || header[0] != "usage_id" || header[1] != "customer_id" ||
440			header[2] != "time" || header[3] != "quantity" {
441			return nil, []string{fmt.Sprintf("表头必须是 %s，实际为 %s", usageHeader, strings.Join(header, ","))}
442		}
443	
444		var rows []*parsedRow
445		var problems []string
446		line := 1
447		for {
448			rec, err := cr.Read()
449			if err == io.EOF {
450				break
451			}
452			line++
453			if err != nil {
454				problems = append(problems, fmt.Sprintf("第 %d 行：CSV 格式错误：%v", line, err))
455				if pe, ok := err.(*csv.ParseError); ok && pe.Err == csv.ErrFieldCount {
456					// 字段数错误后继续读取仍可能拿到错乱记录，直接终止解析。
457					break
458				}
459				continue
460			}
461			for i := range rec {
462				rec[i] = strings.TrimSpace(rec[i])
463			}
464	
465			id, custID, ts, qtyText := rec[0], rec[1], rec[2], rec[3]
466			if id == "" {
467				problems = append(problems, fmt.Sprintf("第 %d 行：用量标识不能为空", line))
468				continue
469			}
470			if custID == "" {
471				problems = append(problems, fmt.Sprintf("第 %d 行：客户标识不能为空", line))
472				continue
473			}
474			t, err := time.Parse(time.RFC3339, ts)
475			if err != nil {
476				problems = append(problems, fmt.Sprintf("第 %d 行：时间 %q 不是 RFC3339 格式：%v", line, ts, err))
477				continue
478			}
479			qty, err := strconv.ParseInt(qtyText, 10, 64)
480			if err != nil {
481				problems = append(problems, fmt.Sprintf("第 %d 行：数量 %q 不是有符号 64 位整数", line, qtyText))
482				continue
483			}
484			if qty <= 0 {
485				problems = append(problems, fmt.Sprintf("第 %d 行：数量必须是正整数，收到 %d", line, qty))
486				continue
487			}
488	
489			rows = append(rows, &parsedRow{
490				line: line,
491				rec:  usageRecord{ID: id, CustomerID: custID, Time: ts, Quantity: qty},
492				t:    t,
493			})
494		}
495		return rows, problems
496	}
497	
498	// sameUsage 按（客户、解析后的时间点、数量）判定两条记录内容是否相同，
499	// 时间比较的是瞬间，因此 Z 与 +08:00 表示同一时刻视为相同。
500	func sameUsage(existing *usageRecord, candidate *usageRecord, candidateT time.Time) bool {
501		if existing.CustomerID != candidate.CustomerID || existing.Quantity != candidate.Quantity {
502			return false
503		}
504		et, err := time.Parse(time.RFC3339, existing.Time)
505		if err != nil {
506			return existing.Time == candidate.Time
507		}
508		return et.Equal(candidateT)
509	}
510	
511	// validMonth 严格校验 YYYY-MM（月份两位、01..12）。
512	func validMonth(m string) bool {
513		t, err := time.Parse("2006-01", m)
514		if err != nil || t.Format("2006-01") != m || t.Year() < 1 {
515			return false
516		}
517		return true
518	}
519	
520	// inMonth 判定一条 RFC3339 时间（换算 UTC 后）是否落在给定自然月。
521	func inMonth(rfc3339, month string) bool {
522		t, err := time.Parse(time.RFC3339, rfc3339)
523		if err != nil {
524			return false
525		}
526		return t.UTC().Format("2006-01") == month
527	}
528	
529	// utcMonth 返回 RFC3339 时间换算 UTC 后的自然月（YYYY-MM）。
530	// 入参时间均已在载入/导入时校验为 RFC3339。
531	func utcMonth(rfc3339 string) string {
532		t, _ := time.Parse(time.RFC3339, rfc3339)
533		return t.UTC().Format("2006-01")
534	}
