619	// monthUsage 归集客户在某 UTC 自然月（左闭右开 [月初, 下月初)）内的全部
620	// 有效（未撤回）用量，并按计价顺序（解析后的时间点升序、同一时间按标识
621	// 字典序）排列。已撤回用量不计费用，不参与单笔及批量结算；阶梯计价将剩余
622	// 记录按原有时间点及标识顺序从零累计重新分档。
623	func monthUsage(s *state, customerID, month string) []*usageRecord {
624		var recs []*usageRecord
625		for _, u := range s.Usage {
626			if s.isWithdrawn(u.ID) {
627				continue
628			}
629			if u.CustomerID == customerID && inMonth(u.Time, month) {
630				recs = append(recs, u)
631			}
632		}
633		sortByInstant(recs)
634		return recs
635	}
636	
637	// buildFixedBill 为固定单价客户构造账单（不落盘）：逐条 数量×单价 并汇总，
638	// 全程整数运算，任何一步溢出都返回错误。recs 须已按计价顺序排列。
639	func buildFixedBill(cust *customer, month string, recs []*usageRecord) (*bill, error) {
640		lines := make([]billLine, 0, len(recs))
641		var totalQty, totalFee int64
642		for _, u := range recs {
643			lineFee, err := mul64(u.Quantity, cust.Price)
644			if err != nil {
645				return nil, fmt.Errorf("用量 %s：数量 %d × 单价 %d 金额溢出", u.ID, u.Quantity, cust.Price)
646			}
647			if totalQty, err = add64(totalQty, u.Quantity); err != nil {
648				return nil, fmt.Errorf("汇总数量溢出有符号 64 位整数范围")
649			}
650			if totalFee, err = add64(totalFee, lineFee); err != nil {
651				return nil, fmt.Errorf("汇总金额溢出有符号 64 位整数范围")
652			}
653			lines = append(lines, billLine{
654				UsageID:  u.ID,
655				Time:     u.Time,
656				Quantity: u.Quantity,
657				LineFee:  lineFee,
658			})
659		}
660		return &bill{
661			ID:         stableBillID(cust.ID, month),
662			CustomerID: cust.ID,
663			Month:      month,
664			TotalQty:   totalQty,
665			UnitPrice:  cust.Price,
666			TotalFee:   totalFee,
667			Lines:      lines,
668			CreatedAt:  time.Now().UTC().Format(time.RFC3339),
669		}, nil
670	}
671	
672	func sortByInstant(us []*usageRecord) {
673		// 入参时间均已在载入/导入时校验为 RFC3339。
674		sort.Slice(us, func(i, j int) bool {
675			ti, _ := time.Parse(time.RFC3339, us[i].Time)
676			tj, _ := time.Parse(time.RFC3339, us[j].Time)
677			ui, uj := ti.UTC(), tj.UTC()
678			if !ui.Equal(uj) {
679				return ui.Before(uj)
680			}
681			return us[i].ID < us[j].ID
682		})
683	}
