// draftsForCustomerMonth 返回某客户某月份的全部草案（含待确认与已确认），
// 按草案标识排序；当前无调用方依赖，保留以便查询与诊断。
func draftsForCustomerMonth(s *state, customerID, month string) []*settlementDraft {
	var list []*settlementDraft
	for _, d := range s.Drafts {
		if d.CustomerID == customerID && d.Month == month {
			list = append(list, d)
		}
	}
	sort.Slice(list, func(i, j int) bool { return list[i].ID < list[j].ID })
	return list
}

